int Stub::OnRemoteRequest(uint32_t transaction,MessageParcel &incoming,MessageParcel &outgoing,MessageOption &option) {
if (incoming.ReadInterfaceToken() != GetDescriptor()) return -1;
switch(transaction){ case 1: if (AccessTokenKit::VerifyAccessToken(IPCSkeleton::GetCallingTokenID(), "ohos.permission.HOLDOUT") != PERMISSION_GRANTED) return -1;
 StartAbility(); break; case 2: StartAbility(); break; default: return -1;}
return 0;
}

